//! Parity test for `can(actor, action, resource)` against the TypeScript
//! `packages/core/src/permissions.ts`. Golden values are generated by
//! `apps/api/scripts/permissions-golden.mts`.

use serde_json::Value;
use taff_core::{
    Action, Actor, Capability, GrantStatus, MemberKind, PermissionDecision, Resource, ReviewPolicy,
    Role, Scope, TaskStatus, can,
};

fn golden() -> Vec<(String, bool)> {
    let raw = include_str!("fixtures/permissions-golden.json");
    let arr: Vec<Value> = serde_json::from_str(raw).expect("golden must be valid JSON");
    arr.into_iter()
        .map(|v| {
            let name = v["name"].as_str().unwrap().to_string();
            let result = v["result"].as_bool().unwrap();
            (name, result)
        })
        .collect()
}

fn person() -> Actor {
    Actor {
        id: "person".into(),
        workspace_id: "ws".into(),
        user_id: Some("person".into()),
        name: "Person".into(),
        kind: MemberKind::Person,
        role: Role::Member,
        ..Default::default()
    }
}

fn agent() -> Actor {
    Actor {
        id: "agent".into(),
        workspace_id: "ws".into(),
        user_id: Some("agent".into()),
        name: "Agent".into(),
        kind: MemberKind::Agent,
        role: Role::Member,
        scopes: vec![
            Scope::TasksRead,
            Scope::TasksWrite,
            Scope::CalendarWrite,
            Scope::InboxReview,
            Scope::FilesWrite,
        ],
        review_policy: ReviewPolicy::AlwaysReview,
        ..Default::default()
    }
}

fn task() -> Resource {
    Resource {
        workspace_id: Some("ws".into()),
        owner_id: Some("person".into()),
        worker_id: Some("agent".into()),
        ..Default::default()
    }
}

/// Builds the same 50 cases as the TypeScript generator and compares each
/// decision against the golden `result`.
#[test]
fn permissions_match_node_golden() {
    let expected = golden();
    let expected_map: std::collections::HashMap<&str, bool> =
        expected.iter().map(|(n, r)| (n.as_str(), *r)).collect();

    // A list of (name, actor-or-None, action, resource) mirrors
    // apps/api/scripts/permissions-golden.mts.
    let mut results: Vec<(String, bool)> = Vec::new();

    let mut push = |name: &str, actor: Option<&Actor>, action: Action, resource: &Resource| {
        results.push((name.to_string(), can(actor, action, resource)));
    };

    // project:stage
    let mut admin = person();
    admin.role = Role::Admin;
    push(
        "admin moves stage",
        Some(&admin),
        Action::ProjectStage,
        &task(),
    );

    push(
        "lead moves stage",
        Some(&person()),
        Action::ProjectStage,
        &Resource {
            lead_id: Some("person".into()),
            ..task()
        },
    );
    push(
        "other member cannot move stage",
        Some(&person()),
        Action::ProjectStage,
        &task(),
    );
    let mut guest = person();
    guest.role = Role::Guest;
    push(
        "guest lead cannot move stage",
        Some(&guest),
        Action::ProjectStage,
        &Resource {
            lead_id: Some("person".into()),
            ..task()
        },
    );
    push(
        "agent cannot move stage",
        Some(&agent()),
        Action::ProjectStage,
        &Resource {
            lead_id: Some("agent".into()),
            ..task()
        },
    );
    push(
        "other workspace denied",
        Some(&person()),
        Action::ProjectStage,
        &Resource {
            workspace_id: Some("other".into()),
            lead_id: Some("person".into()),
            ..task()
        },
    );

    // workspace:default
    push(
        "user selects own default",
        Some(&person()),
        Action::WorkspaceDefault,
        &Resource {
            user_id: Some("person".into()),
            ..Default::default()
        },
    );
    push(
        "user cannot change other default",
        Some(&person()),
        Action::WorkspaceDefault,
        &Resource {
            user_id: Some("other".into()),
            ..Default::default()
        },
    );
    let mut sysadmin = person();
    sysadmin.system_admin = true;
    push(
        "system admin changes other default",
        Some(&sysadmin),
        Action::WorkspaceDefault,
        &Resource {
            user_id: Some("other".into()),
            ..Default::default()
        },
    );
    push(
        "agent cannot change default",
        Some(&agent()),
        Action::WorkspaceDefault,
        &Resource {
            user_id: Some("person".into()),
            ..Default::default()
        },
    );

    // workspace:archive
    push(
        "admin archives own org",
        Some(&admin),
        Action::WorkspaceArchive,
        &task(),
    );
    push(
        "member cannot archive",
        Some(&person()),
        Action::WorkspaceArchive,
        &task(),
    );
    push(
        "system admin archives",
        Some(&sysadmin),
        Action::WorkspaceArchive,
        &task(),
    );
    push(
        "agent cannot archive",
        Some(&agent()),
        Action::WorkspaceArchive,
        &task(),
    );

    // read / create / assign
    push(
        "anonymous cannot read",
        None,
        Action::WorkspaceRead,
        &task(),
    );
    push(
        "member can read",
        Some(&person()),
        Action::WorkspaceRead,
        &task(),
    );
    push(
        "other workspace read denied",
        Some(&person()),
        Action::WorkspaceRead,
        &Resource {
            workspace_id: Some("other".into()),
            ..Default::default()
        },
    );
    push(
        "person can create",
        Some(&person()),
        Action::TaskCreate,
        &task(),
    );
    push(
        "owner can assign",
        Some(&person()),
        Action::TaskAssign,
        &task(),
    );
    push(
        "other member cannot assign",
        Some(&person()),
        Action::TaskAssign,
        &Resource {
            owner_id: Some("other".into()),
            ..task()
        },
    );
    push(
        "admin can assign",
        Some(&admin),
        Action::TaskAssign,
        &Resource {
            owner_id: Some("other".into()),
            ..task()
        },
    );
    push(
        "admin isolated",
        Some(&admin),
        Action::TaskAssign,
        &Resource {
            workspace_id: Some("other".into()),
            ..task()
        },
    );

    // task status
    push(
        "owner moves status",
        Some(&person()),
        Action::TaskStatus,
        &Resource {
            to: Some(TaskStatus::InProgress),
            ..task()
        },
    );
    let mut worker = person();
    worker.id = "worker".into();
    push(
        "worker moves status",
        Some(&worker),
        Action::TaskStatus,
        &Resource {
            worker_id: Some("worker".into()),
            to: Some(TaskStatus::NeedsReview),
            ..task()
        },
    );
    let mut other = person();
    other.id = "other".into();
    push(
        "bystander cannot move status",
        Some(&other),
        Action::TaskStatus,
        &Resource {
            to: Some(TaskStatus::InProgress),
            ..task()
        },
    );

    // capability:use
    push(
        "agent uses tasks.write capability",
        Some(&agent()),
        Action::CapabilityUse,
        &Resource {
            capability: Some(Capability::TasksWrite),
            ..task()
        },
    );
    push(
        "agent denied projects.manage",
        Some(&agent()),
        Action::CapabilityUse,
        &Resource {
            capability: Some(Capability::ProjectsManage),
            ..task()
        },
    );
    let mut noscope = agent();
    noscope.scopes.clear();
    push(
        "agent missing scope",
        Some(&noscope),
        Action::CapabilityUse,
        &Resource {
            capability: Some(Capability::TasksWrite),
            ..task()
        },
    );
    push(
        "person capability always uses",
        Some(&person()),
        Action::CapabilityUse,
        &Resource {
            capability: Some(Capability::ProjectsManage),
            ..task()
        },
    );

    // suggestion
    push(
        "admin creates suggestion",
        Some(&admin),
        Action::SuggestionCreate,
        &task(),
    );
    push(
        "agent creates suggestion on own work",
        Some(&agent()),
        Action::SuggestionCreate,
        &Resource {
            worker_id: Some("agent".into()),
            ..task()
        },
    );
    push(
        "agent cannot create suggestion on others work",
        Some(&agent()),
        Action::SuggestionCreate,
        &Resource {
            worker_id: Some("other".into()),
            ..task()
        },
    );
    push(
        "person decides suggestion",
        Some(&person()),
        Action::SuggestionDecide,
        &task(),
    );

    // run / finish
    push(
        "agent starts run on own work",
        Some(&agent()),
        Action::RunStart,
        &Resource {
            worker_id: Some("agent".into()),
            ..task()
        },
    );
    push(
        "agent cannot start run on other work",
        Some(&agent()),
        Action::RunStart,
        &Resource {
            worker_id: Some("other".into()),
            ..task()
        },
    );
    let mut askonly = agent();
    askonly.review_policy = ReviewPolicy::AskOnly;
    push(
        "agent finishes own non-review task ask_only",
        Some(&askonly),
        Action::TaskFinish,
        &Resource {
            worker_id: Some("agent".into()),
            requested_review: Some(false),
            ..task()
        },
    );
    push(
        "agent cannot finish always_review",
        Some(&agent()),
        Action::TaskFinish,
        &Resource {
            worker_id: Some("agent".into()),
            requested_review: Some(false),
            ..task()
        },
    );

    // token / review
    push(
        "person manages token (admin)",
        Some(&admin),
        Action::TokenManage,
        &task(),
    );
    push(
        "agent cannot manage token",
        Some(&agent()),
        Action::TokenManage,
        &task(),
    );
    push(
        "agent cannot review task",
        Some(&agent()),
        Action::TaskReview,
        &task(),
    );

    // grant
    push(
        "agent requests grant for itself",
        Some(&agent()),
        Action::GrantRequest,
        &Resource {
            agent_id: Some("agent".into()),
            capability: Some(Capability::TasksWrite),
            ..task()
        },
    );
    push(
        "agent requests grant for other",
        Some(&agent()),
        Action::GrantRequest,
        &Resource {
            agent_id: Some("other".into()),
            capability: Some(Capability::TasksWrite),
            ..task()
        },
    );
    push(
        "admin decides grant",
        Some(&admin),
        Action::GrantDecide,
        &task(),
    );

    // crm / contact
    push(
        "person reads contact",
        Some(&person()),
        Action::ContactRead,
        &task(),
    );
    let mut crm_allow = agent();
    crm_allow.permissions = vec![(Capability::CrmRead, PermissionDecision::Allow)];
    push(
        "agent reads contact with crm.read allow",
        Some(&crm_allow),
        Action::ContactRead,
        &task(),
    );
    push(
        "agent read contact denied by default ask",
        Some(&agent()),
        Action::ContactRead,
        &task(),
    );
    let mut crm_details = agent();
    crm_details.permissions = vec![
        (Capability::CrmRead, PermissionDecision::Allow),
        (Capability::CrmContactDetails, PermissionDecision::Allow),
    ];
    push(
        "agent reads contact details with allow",
        Some(&crm_details),
        Action::ContactDetails,
        &task(),
    );

    // finance / mind
    push(
        "person reads finance",
        Some(&person()),
        Action::FinanceRead,
        &task(),
    );
    push(
        "person manages finance admin",
        Some(&admin),
        Action::FinanceManage,
        &task(),
    );
    push(
        "member cannot manage finance",
        Some(&person()),
        Action::FinanceManage,
        &task(),
    );

    // Compare each result to the golden map.
    assert_eq!(results.len(), expected_map.len(), "case count drift");
    for (name, result) in &results {
        let want = expected_map
            .get(name.as_str())
            .unwrap_or_else(|| panic!("missing golden for {name}"));
        assert_eq!(result, want, "can() mismatch for {name}");
    }

    // Exercise the OAuth ceiling and scope_name so the port is fully covered
    // (and not flagged dead code).
    assert!(taff_core::can_grant_oauth_scopes(
        Some(&admin),
        &task(),
        &[Scope::TasksRead, Scope::TasksWrite],
    ));
    assert!(!taff_core::can_grant_oauth_scopes(
        Some(&guest),
        &task(),
        &[Scope::TasksRead],
    ));
    assert_eq!(taff_core::scope_name(Scope::TasksRead), "tasks:read");
    let _ = GrantStatus::Allowed;
}
